Item.method_code:
/*
    開達書式のリンクタブで選択したリンクアイテムのURLを開く
    URLのバリデーションなどはしない
    
    注意：ブラウザ側で標準でブロックされるので、Arasの推奨通りブロックしない設定が必要
            さもないと1つ目のURLしか表示されない
*/
const {
  getState,
  rows
} = options;
const { grid } = getState();

if (grid.selectedRows.length == 0) {
  return;
}

let timeStamp = new Date().getTime();
let count = 1;
for(const id of grid.selectedRows)
{
    const url = rows.get(id, 'h4_urllink');
    if(url)
    {
        //新しいタブでそれぞれ開くためにタブ名を固有に
        window.open(url, '_blank' + timeStamp + count);
        //window.open(url, '_blank' + timeStamp + count,'popup');//ポップアップ版
        count = count +1;
    }
}
